## 常见缓存策略

```mermaid
flowchart TD
    subgraph CacheFirst["Cache First"]
        CF1["请求"] --> CF2{"缓存命中?"}
        CF2 -- 是 --> CF3["返回缓存"]
        CF2 -- 否 --> CF4["请求网络"]
        CF4 --> CF5["缓存并返回"]
    end
    subgraph NetworkFirst["Network First"]
        NF1["请求"] --> NF2["请求网络"]
        NF2 -->|成功| NF3["缓存并返回"]
        NF2 -->|失败| NF4["返回缓存"]
    end
    subgraph StaleWhileRevalidate["Stale While Revalidate"]
        SWR1["请求"] --> SWR2["返回缓存"]
        SWR1 --> SWR3["同时请求网络"]
        SWR3 --> SWR4["更新缓存"]
    end
```

```typescript
type CacheStrategy = 'cache-first' | 'network-first' | 'stale-while-revalidate' | 'network-only' | 'cache-only';

async function cacheFirst(request: Request, cacheName: string): Promise<Response> {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);
  if (cached) return cached;

  const response = await fetch(request);
  if (response.ok) {
    await cache.put(request, response.clone());
  }
  return response;
}

async function networkFirst(request: Request, cacheName: string): Promise<Response> {
  const cache = await caches.open(cacheName);
  try {
    const response = await fetch(request);
    if (response.ok) {
      await cache.put(request, response.clone());
    }
    return response;
  } catch {
    const cached = await cache.match(request);
    if (cached) return cached;
    throw new Error('No network and no cache available');
  }
}

async function staleWhileRevalidate(request: Request, cacheName: string): Promise<Response> {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);

  const fetchPromise = fetch(request).then((response) => {
    if (response.ok) {
      cache.put(request, response.clone());
    }
    return response;
  });

  return cached ?? fetchPromise;
}
```

| 策略                   | 速度     | 新鲜度 | 离线支持 | 适用场景                |
| ---------------------- | -------- | ------ | -------- | ----------------------- |
| Cache First            | 最快     | 低     | ✅       | 静态资源（JS/CSS/图片） |
| Network First          | 较慢     | 高     | ✅       | API 数据、动态内容      |
| Stale While Revalidate | 快       | 中     | ✅       | 频繁更新的资源          |
| Network Only           | 网络速度 | 最高   | ❌       | 实时数据                |
| Cache Only             | 最快     | 无更新 | ✅       | 预缓存的离线资源        |

